export interface ReadingProgressOut {
  done: number;
  total: number;
}

/**
 * wikiapp/wiki_schemas.py MapLinksIn: Relations an edit took off block `id` (its prerequisites / members that pointed at a dropped
 * block or backwards after a reorder): its inverse (撤销) puts them back where they were.
 */
export interface MapLinksIn {
  id: string;
  prereqs?: string[];
  members?: string[];
  before_prereqs?: string[];
  before_members?: string[];
}

/**
 * goals/regions.py MapNode: `prereqs`: same-level edges (siblings under the same parent), acyclic. A node starts
 * `collapsed` and becomes `expanded` once this goal entered it (whether a block not entered is
 * known is K's call: `block_known`); a concept node of an older map is always `expanded`.
 * Whether a node can be split or learned is not its `kind` (wikiapp/node_state, spec
 * 2026-10-28 §2.2). `path_id` / `page_id`: what opening it produced — on any node (a point's
 * path; an older map's region path). `members`: a region's knowledge points (concept ids).
 * `reused`: the wiki already had it before this goal (a topic or a concept; same id everywhere:
 * one node for one thing). `level`: a chat-first block's level word (基础 / 核心 / 进阶 / 拓展,
 * goals/blocks.LEVELS; "" = none: a block added without one, every other node).
 * The goal record per block (S1, D09; written when the goal is made): `diagnose` — whether the
 * diagnosis may ask about it (False: decided *teach*, never asked, also when it is entered);
 * `said` — the learner's own words about it, each quote verbatim (() = none). Its covers are
 * `scope` (joined by 、).
 */
export interface MapNode {
  id: string;
  kind: "region" | "concept";
  name: string;
  parent?: string | null;
  scope?: string;
  prereqs?: string[];
  target?: boolean;
  state?: NodeState;
  path_id?: string | null;
  page_id?: string | null;
  reused?: boolean;
  members?: string[];
  level?: string;
  diagnose?: boolean;
  said?: string[];
}

/** wikiapp/wiki_schemas.py GoalPathOut: One of a goal's paths: a goal split on demand has one per point or block opened. */
export interface GoalPathOut {
  path_id: string;
  name: string;
  path: PathItemOut[];
}

/** wikiapp/wiki_schemas.py WriteProgressOut */
export interface WriteProgressOut {
  section: number;
  of: number | null;
  pass: number | null;
}

/**
 * wikiapp/wiki_schemas.py ReviewFirstOut: 「建议先复习 `name`」 on a step (wikiapp.review_first). `page_id`: the page that teaches it, the
 * chat turn's page (None: no page yet).
 */
export interface ReviewFirstOut {
  node_id: string;
  name: string;
  page_id: string | null;
  page_title: string;
}

/**
 * teach/contracts.py PagePlan: How this page changes right away: paragraphs added to named sections, and at most one
 * library component inserted after a section (component ids come only from the library). A
 * configurable component comes with its `component_config` (validated against the component's
 * schema; invalid → not inserted) and every component with `component_why` (why this one fits).
 */
export interface PagePlan {
  summary: string;
  sections: SectionAddition[];
  component: string | null;
  component_after: string | null;
  component_config: Record<string, unknown> | null;
  component_why: string;
  block: Record<string, unknown> | null;
  block_why: string;
}

/** teach/contracts.py StylePlan: The teaching-rule change this feedback asks for (shown with the feedback's reading). */
export interface StylePlan {
  kind: string;
  before: string;
  after: string;
}

/** wikiapp/wiki_schemas.py NoteOut */
export interface NoteOut {
  entry_id: string;
  cell: string;
  kind: NoteKind;
  text: string;
  evidence_ref: string;
  label: string | null;
}

/** wikiapp/wiki_schemas.py PathConceptOut */
export interface PathConceptOut {
  concept_id: string;
  name: string;
  target: boolean;
}

/** wikiapp/wiki_schemas.py BlockOut */
export interface BlockOut {
  region_id: string;
  name: string;
  level: string;
  state: "not_started" | "diagnosing" | "learning" | "choosing" | "done" | "known";
  path_id: string | null;
  draft_id: string | null;
  pages_done: number;
  pages_total: number;
}

/** wikiapp/wiki_schemas.py ReviewCheckOut */
export interface ReviewCheckOut {
  stem: string;
  options: string[];
}

/** teach/contracts.py AnchorDelta: One fixed anchor metric before vs after a change; `delta` is oriented so + is better. */
export interface AnchorDelta {
  metric: AnchorMetric;
  before: number | null;
  after: number | null;
  delta: number | null;
  lo: number | null;
  hi: number | null;
  n_before: number;
  n_after: number;
}

/** teach/contracts.py SectionAddition */
export interface SectionAddition {
  section_id: string;
  add: string;
}

/** SSE frames: the `event:` name and its JSON payload. */
export type OrganizeEvent =
  | { event: "planning"; data: PlanningEvent }
  | { event: "outline"; data: OutlineEvent }
  | { event: "writer"; data: WriterEvent }
  | { event: "section_added"; data: SectionAddedEvent }
  | { event: "section_delta"; data: SectionDeltaEvent }
  | { event: "section_done"; data: SectionDoneEvent }
  | { event: "done"; data: OrganizeDoneEvent }
  | { event: "error"; data: ErrorEvent };
